<section class="rounded-3xl border border-white/10 bg-white/5 p-6"><h2 class="text-2xl font-black">Checkout Architecture</h2><p class="mt-2 text-slate-400">Guest checkout, user checkout, coupons, wallet, tax, invoices, downloads, and license key generation are represented in SQLite tables.</p></section><div class="mt-6 overflow-x-auto rounded-3xl border border-white/10 bg-white/5"><table class="admin-table"><tr><th>Order</th><th>Product</th><th>Vendor</th><th>Amount</th><th>Status</th></tr><?php foreach ($orders as $order): ?><tr><td><?= e($order['order_number']) ?></td><td><?= e($order['product_name']) ?></td><td><?= e($order['store_name']) ?></td><td><?= money($order['amount']) ?></td><td><?= e($order['payment_status']) ?></td></tr><?php endforeach; ?></table></div>
